local PastryChef = {}
local PRODUCTS = {
    simple_tart = { name = "Preprosta pita", wheatCost = 2, fruitCost = 1, butterCost = 1, time = 2, cost = 18, flavorStrength = 30, happiness = 2, description = "Preprosta sadna pita." },
    honey_cake = { name = "Medena torta", wheatCost = 3, honeyCost = 2, butterCost = 1, time = 4, cost = 50, flavorStrength = 45, happiness = 3, prestige = 2, description = "Medena torta za slovesnosti." },
    spiced_cake = { name = "Začinjena torta", wheatCost = 3, honeyCost = 2, spiceCost = 1, butterCost = 1, time = 6, cost = 120, flavorStrength = 60, happiness = 4, prestige = 4, description = "Začinjena torta z žafranom." },
    marzipan = { name = "Marcipan", almondCost = 2, honeyCost = 2, silverCost = 1, time = 8, cost = 280, flavorStrength = 75, happiness = 5, prestige = 8, description = "Marcipan iz mandljev za plemiče." },
    gold_leaf_pastry = { name = "Zlatolistna peciva", wheatCost = 4, almondCost = 2, goldCost = 1, honeyCost = 2, spiceCost = 1, butterCost = 1, time = 11, cost = 620, flavorStrength = 90, happiness = 7, prestige = 15, description = "Peciva z zlatim lističem za visoke plemiče." },
    royal_grand_pastry = { name = "Kraljevski veliki peciva", wheatCost = 6, almondCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, honeyCost = 3, spiceCost = 2, butterCost = 2, time = 16, cost = 1800, flavorStrength = 100, happiness = 15, prestige = 40, description = "Velika kraljevska peciva z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Pekovska slaščičarna", cost = { gold = 320, wood = 130, stone = 200 }, upkeep = 8, qualityBonus = 5 },
    pastry_kitchen = { name = "Slaščičarna", cost = { gold = 1100, wood = 250, stone = 400, wheat = 8 }, upkeep = 27, qualityBonus = 18 },
    decorating_room = { name = "Okrasovalnica", cost = { gold = 2500, wood = 350, stone = 700, silver = 40, almond = 8 }, upkeep = 60, qualityBonus = 30 },
    royal_pastry_atelier = { name = "Kraljevski atelje slaščic", cost = { gold = 10000, wood = 600, stone = 1000, gold = 80, jewel = 25 }, upkeep = 200, qualityBonus = 55, prestigeBonus = 45 },
}
PastryChef.wheatStock = 18; PastryChef.fruitStock = 14; PastryChef.butterCost = 12; PastryChef.honeyStock = 14; PastryChef.spiceStock = 10; PastryChef.almondStock = 10; PastryChef.silverStock = 8; PastryChef.goldStock = 6; PastryChef.jewelStock = 6
PastryChef.productStock = {}; PastryChef.buildings = {}; PastryChef.maker = nil; PastryChef.activeMaking = {}; PastryChef.totalProducts = 0; PastryChef.dayTimer = 0
function PastryChef.init() PastryChef.wheatStock=18; PastryChef.fruitStock=14; PastryChef.butterCost=12; PastryChef.honeyStock=14; PastryChef.spiceStock=10; PastryChef.almondStock=10; PastryChef.silverStock=8; PastryChef.goldStock=6; PastryChef.jewelStock=6; PastryChef.productStock={}; PastryChef.buildings={}; PastryChef.maker=nil; PastryChef.activeMaking={}; PastryChef.totalProducts=0; PastryChef.dayTimer=0; print("[PastryChef] Royal Pastry Chef System initialized (6 products, 4 buildings)") end
function PastryChef.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PastryChef.maker={name=n or ("Slaščičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Slaščičar najet: %s (spretnost: %d)",PastryChef.maker.name,s),"success") end; return true end
function PastryChef.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PastryChef.build(id) local ok,e=PastryChef.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PastryChef.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PastryChef.getQualityBonus() local b=0; for _,bd in ipairs(PastryChef.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PastryChef.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.wheatCost and PastryChef.wheatStock<(d.wheatCost or 0) then return false,"Premalo pšenice" end; if d.fruitCost and PastryChef.fruitStock<(d.fruitCost or 0) then return false,"Premalo sadja" end; if d.butterCost and PastryChef.butterCost<(d.butterCost or 0) then return false,"Premalo masla" end; if d.honeyCost and PastryChef.honeyStock<(d.honeyCost or 0) then return false,"Premalo medu" end; if d.spiceCost and PastryChef.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.almondCost and PastryChef.almondStock<(d.almondCost or 0) then return false,"Premalo mandljev" end; if d.silverCost and PastryChef.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PastryChef.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PastryChef.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #PastryChef.buildings==0 then return false,"Potrebna delavnica" end; if not PastryChef.maker then return false,"Potreben slaščičar" end; return true end
function PastryChef.make(pt,qty) qty=qty or 5; local ok,e=PastryChef.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.wheatCost then PastryChef.wheatStock=PastryChef.wheatStock-d.wheatCost*qty end; if d.fruitCost then PastryChef.fruitStock=PastryChef.fruitStock-d.fruitCost*qty end; if d.butterCost then PastryChef.butterCost=PastryChef.butterCost-d.butterCost*qty end; if d.honeyCost then PastryChef.honeyStock=PastryChef.honeyStock-d.honeyCost*qty end; if d.spiceCost then PastryChef.spiceStock=PastryChef.spiceStock-d.spiceCost*qty end; if d.almondCost then PastryChef.almondStock=PastryChef.almondStock-d.almondCost*qty end; if d.silverCost then PastryChef.silverStock=PastryChef.silverStock-d.silverCost*qty end; if d.goldCost then PastryChef.goldStock=PastryChef.goldStock-d.goldCost*qty end; if d.jewelCost then PastryChef.jewelStock=PastryChef.jewelStock-d.jewelCost*qty end; local t=d.time; if PastryChef.maker then t=math.max(1,t-math.floor(PastryChef.maker.skill/12)) end; table.insert(PastryChef.activeMaking,{id="pastry_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flavorStrength=d.flavorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PastryChef.completeMaking(m) local q=1.0+(PastryChef.getQualityBonus()/100); if PastryChef.maker then q=q+(PastryChef.maker.skill/180) end; q=math.min(2.0,q); PastryChef.productStock[m.productType]=(PastryChef.productStock[m.productType] or 0)+m.quantity; PastryChef.totalProducts=PastryChef.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PastryChef.maker then PastryChef.maker.itemsMade=PastryChef.maker.itemsMade+m.quantity; if math.random()<0.20 then PastryChef.maker.skill=math.min(100,PastryChef.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pecivo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pastry.completed",{productName=m.productName,flavorStrength=m.flavorStrength,happiness=m.happiness}) end end
function PastryChef.update(dt) if not _G.state then return end; PastryChef.dayTimer=PastryChef.dayTimer+dt; if PastryChef.dayTimer>=30 then PastryChef.dayTimer=0; for i=#PastryChef.activeMaking,1,-1 do local m=PastryChef.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PastryChef.completeMaking(m); table.remove(PastryChef.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PastryChef.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PastryChef.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PastryChef.getStats() return {wheatStock=PastryChef.wheatStock,fruitStock=PastryChef.fruitStock,butterCost=PastryChef.butterCost,honeyStock=PastryChef.honeyStock,spiceStock=PastryChef.spiceStock,almondStock=PastryChef.almondStock,silverStock=PastryChef.silverStock,goldStock=PastryChef.goldStock,jewelStock=PastryChef.jewelStock,productStock=PastryChef.productStock,numBuildings=#PastryChef.buildings,hasMaker=PastryChef.maker~=nil,makerName=PastryChef.maker and PastryChef.maker.name or "—",makerSkill=PastryChef.maker and PastryChef.maker.skill or 0,activeMaking=#PastryChef.activeMaking,totalProducts=PastryChef.totalProducts} end
return PastryChef
